/* image path resolver: maps relative img/s/*.jpg and ui/hq/*.png to Shopify CDN via ENSO_IMG_MAP */
function _img(src){
  if(!src||src.startsWith('data:')||src.startsWith('http')||src.startsWith('//')){return src;}
  const base=src.replace(/^.*\//,'').replace(/\.(jpg|jpeg|png|gif|webp)$/i,'');
  return(window.ENSO_IMG_MAP&&window.ENSO_IMG_MAP[base])?window.ENSO_IMG_MAP[base]:src;
}
