const PARTS_IMG = {front:"data:image/jpeg;base64,", back:"data:image/jpeg;base64,"};
const IC_DIA = {'d-clean':'cleaning','df-power':'wont-turn-on','df-battery':'battery','df-else':'weak-smoke','d-first':'battery','d-power':'turn-on','d-hookah':'hose','d-cap':'packing','d-airflow':'draw','d-care':'cleaning'};
const ic = id => (IC_DIA[id] ? ICONS[IC_DIA[id]] : null) || ICONS[id] || ICONS._sparkle;

/* ════════ MODEL TABS ════════ */
let model = 'enso2', lastDevice = 'enso2';

/* ════════ ENSŌ 2.0 VISIBILITY ════════
   Nothing about 2.0 is deleted — it is only hidden while Diamond has the spotlight.
   MAGIC PHRASE: type "wake up 2.0" in the search box to bring it all back.
   Type "sleep 2.0" to hide it again. The choice is remembered on the device. */
let SHOW_E2 = false;
try{ SHOW_E2 = localStorage.getItem('enso2Visible') === 'on'; }catch(e){}
if(!SHOW_E2){ model = 'enso'; lastDevice = 'enso'; }
function setE2Visible(on){
  SHOW_E2 = on;
  try{ localStorage.setItem('enso2Visible', on ? 'on' : 'off'); }catch(e){}
  location.reload();
}
function e2Label(name){ return (!SHOW_E2 && name === 'ENSŌ 2.0') ? 'ENSŌ' : name; }
function applyE2Visibility(){
  const tab = document.getElementById('mtab-enso2');
  if(tab) tab.style.display = SHOW_E2 ? '' : 'none';
  if(!SHOW_E2){
    const hero = document.getElementById('e2Hero'); if(hero) hero.style.display = 'none';
  }
  document.querySelectorAll('.rc-filters .rc-chip').forEach(c=>{
    const t = c.textContent.trim();
    if(t === 'ENSŌ 2.0' || t === 'ENSŌ') c.textContent = SHOW_E2 ? 'ENSŌ 2.0' : 'ENSŌ';
  });
  const btns = [...document.querySelectorAll('#crModel button, #regModel button')];
  btns.forEach(b=>{
    if(b.textContent.trim() === 'ENSŌ 2.0'){
      b.style.display = SHOW_E2 ? '' : 'none';
      if(!SHOW_E2 && b.classList.contains('on')){ b.classList.remove('on'); btns[0].classList.add('on'); }
    }
  });
  if(typeof tempModeUI === 'function') tempModeUI();
}

function setModel(m){
  if(m === 'enso2' && !SHOW_E2) m = 'enso';
  model = m;
  if(m!=='diamond') lastDevice = m;
  DEFAULT_STAGE = STAGE_BY_MODEL[m];
  document.querySelector('.model-tabs').classList.remove('dim');
  document.getElementById('mtab-enso').classList.toggle('on', m==='enso');
  document.getElementById('mtab-enso2').classList.toggle('on', m==='enso2');
  document.getElementById('mtab-diamond').classList.toggle('on', m==='diamond');
  const e2 = document.getElementById('e2Hero'); if(e2) e2.style.display = m==='enso2' ? '' : 'none';
  if(typeof toggleNews==='function' && newsOpen) toggleNews(false);
  go('search');
  document.getElementById('wrap').scrollTop = 0;
}

function renderDiaSoon(which){
  const t = which==='howto' ? 'How to use Diamond' : 'Diamond troubleshooting';
  document.getElementById('scr-diasoon').innerHTML = `
    <div class="soon-card" style="margin-top:24px"><span class="soon-tag">COMING SOON</span>
      <h3 style="font-size:17px;font-weight:600;margin:10px 0 6px">${t}</h3>
      <p>The guides land here when Diamond ships in October 2026.</p></div>
    <div class="footer-note">Questions now? <a href="mailto:${SUPPORT}">${SUPPORT}</a></div>`;
}

/* ════════ NAV ════════ */
function go(name){
  /* Nothing is reachable until a warranty is registered — the app is the registration. */
  document.querySelectorAll('.scr').forEach(s=>s.classList.remove('active'));
  let target = name;
  if(model === 'diamond'){
    if(false){ /* site build: Diamond uses the same home */ }
    else if(name==='howto'){ target = 'dhow'; }
    else if(name==='fix'){ target = 'dfix'; }
  }
  document.getElementById('scr-'+target).classList.add('active');
  document.body.classList.toggle('onboarding', target.indexOf('ob-') === 0);
  if(target === 'notify') renderNotify();
  if(target === 'profile') renderProfile(false);
  if(target === 'register'){ regOpenedAt = Date.now(); regValidate(); applyE2Visibility(); regShot(); }
  renderNtBar();
  document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('on', b.dataset.s===name));
  document.getElementById('wrap').scrollTop = 0;
  const mt = document.querySelector('.model-tabs');
  if(name==='recipes'){ mt.classList.add('dim'); setStage(PRIZE_CUP, 'The prize — win it with your blend'); }
  else { mt.classList.remove('dim'); resetStage(); }
}

/* ════════ RENDER HELPERS ════════ */
let _seenAcc = null;
function upsellBlock(e){
  if(!e.upsell) return '';
  const p = ACC[e.upsell.acc];
  if(!p) return '';
  if(_seenAcc && _seenAcc.has(e.upsell.acc)) return '';
  if(_seenAcc) _seenAcc.add(e.upsell.acc);
  const img = p.img ? `<span class="up-img"><img src="${p.img}" loading="lazy" alt="" onerror="this.parentElement.style.display='none'"></span>` : '';
  const body = `${img}
    <span class="up-body">
      <div class="up-tag">${p.url ? 'UPGRADE YOUR UNIT' : 'COMING SOON'}</div>
      <div class="up-txt">${e.upsell.hook}</div>
      <div class="up-price">${p.name}${p.price ? ' · ' + p.price : ''}</div>
    </span>
    <span class="up-go">${p.url ? '→' : ''}</span>`;
  return p.url
    ? `<a class="upsell" href="${p.url}" target="_blank" rel="noopener">${body}</a>`
    : `<div class="upsell" style="cursor:default">${body}</div>`;
}
function videoBlock(e){
  if(!e.video) return '';
  const durChip = e.dur ? `<span class="vc-dur">${e.dur}</span>` : '';
  if(e.thumb){
    return `<a class="vid-card" href="${e.video}" target="_blank" rel="noopener">
      <span class="vc-wrap"><img src="${e.thumb}" loading="lazy" alt="" onerror="this.style.display='none'">${durChip}</span>
      <span class="vc-bar">
        <span class="vc-play"><svg viewBox="0 0 10 12"><path d="M0 0l10 6-10 6z"/></svg></span>
        <span class="vc-title">${e.vtitle}</span>
        <span class="vc-src">${e.dur ? e.dur+' · ' : ''}YouTube</span>
      </span>
    </a>`;
  }
  return `<a class="vid-pill" href="${e.video}" target="_blank" rel="noopener">▶ ${e.vtitle} <span class="dur">· ${e.dur || 'YouTube'}</span></a>`;
}
function flowBlock(e){
  return `<div class="flow-hint">Tap a step to see it on the screen above</div>` +
    e.flow.map((f,i)=>`
    <button class="fstep${i===0?' on':''}" id="fs-${e.id}-${i}" onclick="showStep('${e.id}',${i})">
      <span class="fs-num">${i+1}</span>
      <span class="fs-body"><div class="fs-t">${f.t}</div><div class="fs-x">${f.x}</div></span>
      ${f.img?`<span class="fs-eye">${ICONS._eye}</span>`:''}
    </button>`).join('');
}
function showStep(id, i){
  const e = KB.find(x=>x.id===id);
  const f = e.flow[i];
  if(f.img) setStage(f.img, `Step ${i+1} · ${f.t}`, false);
  e.flow.forEach((_,j)=>{
    const el = document.getElementById(`fs-${id}-${j}`);
    if(el) el.classList.toggle('on', j===i);
  });
}
function renderBody(e){
  let out = '';
  if(e.flow) out += flowBlock(e);
  if(e.fig) out += `<div class="figs">${e.fig.map(n=>`<img class="fig fig-l" src="${_img('img/manual/'+n+'-ink.png')}" alt="" loading="lazy"><img class="fig fig-d" src="${_img('img/manual/'+n+'.png')}" alt="" loading="lazy">`).join('')}</div>`;
  if(e.parts) out += `
    <div class="parts-toggle">
      <button class="on" onclick="swapParts(this,'front')">Front view</button>
      <button onclick="swapParts(this,'back')">Back view</button>
    </div>
`;
  if(e.a) out += `<p style="margin-top:8px">${e.a}</p>`;
  if(e.steps){ const st = e.steps.concat(model==='enso2' && e.steps2 ? e.steps2 : []); out += `<ol>${st.map(s=>`<li>${s}</li>`).join('')}</ol>`; }
  if(e.sections) out += e.sections.map((sec, i)=>
    `<div class="sec-h${i ? ' more' : ''}">${sec.t}</div>` +
    (sec.steps ? `<ol>${sec.steps.map(x=>`<li>${x}</li>`).join('')}</ol>` : '') +
    (sec.p ? `<p>${sec.p}</p>` : '')
  ).join('');
  if(e.link) out += `<a class="dia-btn" style="display:block;margin-top:12px" href="${e.link.url}" target="_blank" rel="noopener">${e.link.l}</a>`;
  out += videoBlock(e);
  out += upsellBlock(e);
  if(e.upsell2) out += upsellBlock({upsell:e.upsell2});
  if(e.accs) out += e.accs.map(a=>upsellBlock({upsell:a})).join('');
  // 3 Oct, Vadim: fewer "write to us"; one support line at the foot of the list is enough
  return out;
}
function swapParts(btn, side){
  btn.parentElement.querySelectorAll('button').forEach(b=>b.classList.remove('on'));
  btn.classList.add('on');
  setStage(PARTS_IMG[side], side==='front' ? 'ENSŌ Parts · Front view' : 'ENSŌ Parts · Back view');
}

/* ════════ SEARCH ════════ */
/* ════════ DIAMOND SEARCH ════════ */
function diaSearch(){
  const q = document.getElementById('diaQ').value.trim();
  const box = document.getElementById('diaResults');
  document.getElementById('diaChips').style.display = q ? 'none' : '';
  if(!q){ box.innerHTML=''; return; }
  const words = q.toLowerCase().split(/\s+/);
  const pool = KB.filter(e=>e.cat==='dhow'||e.cat==='dfix'||e.cat==='dfaq');
  const ranked = pool.map(e=>({e,s:score(e,words)})).filter(x=>x.s>=3).sort((a,b)=>b.s-a.s).slice(0,3);
  if(!ranked.length){
    box.innerHTML = `<div class="no-result"><h3>No match yet</h3><p>Try another word, or ask our team — they know Diamond inside out.</p><a class="sup-pill" href="mailto:support@ensoshisha.eu?subject=ENSŌ Diamond: ${encodeURIComponent(q)}">${ICONS._mail} Email support@ensoshisha.eu</a></div>`;
    return;
  }
  _seenAcc = new Set();
  box.innerHTML = ranked.map(({e})=>`<div class="result-card"><h3>${e.q}</h3>${renderBody(e)}</div>`).join('');
  _seenAcc = null;
}

function royInfo(){
  alert("Recipe of the Year — December 2027\n\nEach month's winners roll into the year-end race. The most-loved blend of the year becomes a real product: you co-design a signature blend with ENSŌ and a partner shisha-tobacco house, it carries your recipe's name, goes on sale, and you earn a share of every pack sold.\n\nCreate, share, and keep climbing.");
}

function diaChip(el){ document.getElementById('diaQ').value = el.textContent; diaSearch(); }

function score(entry, words){
  let s = 0;
  const flowText = (entry.flow||[]).map(f=>f.t+' '+f.x).join(' ');
  const hay = (entry.q+' '+entry.kw.join(' ')+' '+(entry.a||'')+' '+(entry.front||'')+' '+(entry.back||'')+' '+(entry.steps||[]).concat(entry.steps2||[]).join(' ')+' '+flowText).toLowerCase();
  for(const w of words){
    if(w.length < 2) continue;
    if(entry.kw.some(k=>k.includes(w))) s += 3;
    if(entry.q.toLowerCase().includes(w)) s += 2;
    if(hay.includes(w)) s += 1;
  }
  return s;
}
function runSearch(){
  const query = document.getElementById('q').value.trim();
  const box = document.getElementById('results');
  const magic = query.toLowerCase().replace(/[^a-z0-9]/g,'');
  if(magic === 'wakeup20' || magic === 'bringback20'){ setE2Visible(true); return; }
  if(magic === 'sleep20' || magic === 'hide20'){ setE2Visible(false); return; }
  if(!query){ box.innerHTML=''; return; }
  const words = query.toLowerCase().split(/\s+/);
  const pool = KB.filter(e=> model==='diamond' ? ['dhow','dfix','dfaq'].includes(e.cat) : !['dhow','dfix','dfaq','dhow-app'].includes(e.cat));
  const ranked = pool.map(e=>({e,s:score(e,words)})).filter(x=>x.s>=3).sort((a,b)=>b.s-a.s).slice(0,3);
  document.getElementById('quickGrid').style.display='none';
  document.getElementById('chips').style.display='none';
  document.getElementById('hintBar').style.display='none';
  if(!ranked.length){
    box.innerHTML = `<div class="no-result">
      <h3>Hmm, I don't have that one yet</h3>
      <p>Our support team knows every corner of ENSŌ — send them a message and they'll sort you out.</p>
      <a class="sup-pill" href="mailto:${SUPPORT}?subject=ENSŌ question: ${encodeURIComponent(query)}">${ICONS._mail} Email ${SUPPORT}</a>
    </div>`;
    return;
  }
  const top = ranked[0].e;
  const stageSrc = top.stageImg || (top.flow ? top.flow[0].img : null);
  if(stageSrc) setStage(stageSrc, top.q, false);
  _seenAcc = new Set();
  box.innerHTML = ranked.map(({e})=>`<div class="result-card"><h3>${e.q}</h3>${renderBody(e)}</div>`).join('');
  _seenAcc = null;
}
function chipSearch(el){
  document.getElementById('q').value = el.textContent;
  runSearch();
}

/* ════════ HINTS ════════ */
let hintIdx = Math.floor(Math.random()*HINTS.length);
function renderHint(){
  const h = HINTS[hintIdx];
  const p = ACC[h.acc];
  document.getElementById('hintBar').innerHTML =
    `<span class="h-ico">${ICONS._sparkle}</span><span class="h-txt">${h.txt} <b style="white-space:nowrap">${p.price ? p.price+' →' : ''}</b></span>`;
  document.getElementById('hintBar').onclick = ()=> { if(p.url) window.open(p.url, '_blank'); else nextHint(); };
}
function nextHint(){ hintIdx = (hintIdx+1)%HINTS.length; renderHint(); }
setInterval(nextHint, 9000);
renderHint();

/* ════════ LIST SCREENS ════════ */
function buildList(cat, mountId){
  document.getElementById(mountId).innerHTML = KB.filter(e=>e.cat===cat).map(e=>`
    <button class="topic" id="t-${e.id}" onclick="toggleTopic('${e.id}')">
      <span class="t-ico">${ic(e.id)}</span>${e.q}<span class="t-arrow">›</span>
    </button>
    <div class="detail" id="d-${e.id}"></div>
  `).join('');
}
function toggleTopic(id){
  const e = KB.find(x=>x.id===id);
  const d = document.getElementById('d-'+id);
  const t = document.getElementById('t-'+id);
  const isOpen = d.classList.contains('visible');
  KB.filter(x=>x.cat===e.cat).forEach(x=>{
    const dx = document.getElementById('d-'+x.id);
    dx.classList.remove('visible'); dx.innerHTML='';
    document.getElementById('t-'+x.id).classList.remove('open');
  });
  if(isOpen){ resetStage(); return; }
  d.innerHTML = renderBody(e);
  d.classList.add('visible');
  t.classList.add('open');
  const stageSrc = e.stageImg || (e.flow ? (e.flow.find(f=>f.img)||{}).img : null);
  if(stageSrc) setStage(stageSrc, e.flow ? `Step 1 · ${e.flow[0].t}` : e.q, false); else resetStage();
  setTimeout(()=>t.scrollIntoView({behavior:'smooth', block:'start'}), 120);
}
function jumpTo(screen, topicId){
  go(screen==='fix'?'fix':'howto');
  setTimeout(()=>toggleTopic(topicId), 150);
}

/* ════════ INIT ════════ */
document.querySelectorAll('.qc-ic').forEach(el=>{ el.innerHTML = ic(el.dataset.ic); });
const rc = document.getElementById('recipesCircle'); if(rc) rc.innerHTML = ICONS._enso;
buildList('howto','howtoList');
buildList('dhow','dhowList');
buildList('dfix','dfixList');
buildList('fix','fixList');
buildList('warranty','warrantyList');
document.getElementById('q').addEventListener('input', function(){
  if(!this.value.trim()){
    document.getElementById('results').innerHTML='';
    document.getElementById('quickGrid').style.display='';
    document.getElementById('chips').style.display='';
    document.getElementById('hintBar').style.display='';
    resetStage();
  }
});

