/* ── thermodial pickers (ENSŌ / 2.0): tap or drag, 15° stops like the photo ── */
const STOPS = [180,195,210,225,240,255,270,285,300,315,330];
const ang = t => (-135 + (t-180)/150*270);
function dialSVG(id){
  let ticks='', labels='';
  for(let t=180;t<=330;t+=5){
    const a=ang(t)*Math.PI/180, major=(t-180)%15===0, r1=major?41:45, r2=51;
    ticks += `<line class="tk" data-t="${t}" x1="${60+r1*Math.sin(a)}" y1="${60-r1*Math.cos(a)}" x2="${60+r2*Math.sin(a)}" y2="${60-r2*Math.cos(a)}" stroke="#2C2825" stroke-width="${major?1.6:0.9}" stroke-linecap="round"/>`;
    if(major) labels += `<text class="lb" data-t="${t}" x="${60+57*Math.sin(a)}" y="${60-57*Math.cos(a)+2.5}" text-anchor="middle" font-size="6.6" font-weight="600" fill="#6B6560">${t}°</text>`;
  }
  return `<svg viewBox="0 0 120 120" id="${id}Svg" style="touch-action:none">
    <circle cx="60" cy="60" r="33" fill="#F7F6F4" stroke="#2C2825" stroke-width="1.6"/>
    ${[...Array(36)].map((_,i)=>{const a=i*10*Math.PI/180;return `<line x1="${60+29*Math.sin(a)}" y1="${60-29*Math.cos(a)}" x2="${60+33*Math.sin(a)}" y2="${60-33*Math.cos(a)}" stroke="#2C2825" stroke-width="1.3"/>`;}).join('')}
    ${ticks}${labels}
    <g class="nd" id="${id}Needle"><path d="M60 60 L58 32 L60 28 L62 32 Z" fill="#2C2825"/></g>
    <circle cx="60" cy="60" r="3" fill="#CFA872"/>
    <text id="${id}Mid" x="60" y="76" text-anchor="middle" font-size="9" font-weight="700" fill="#2C2825">180°</text></svg>`;
}
function dialSet(id, t){ const el=document.getElementById(id); el.value = Math.max(180, Math.min(330, t)); crUpdate(); }
function dialStep(id, d){ const el=document.getElementById(id); dialSet(id, (+el.value||180)+d); }
function dialFromPointer(id, svg, ev){
  const r = svg.getBoundingClientRect(), x = ev.clientX - r.left - r.width/2, y = ev.clientY - r.top - r.height/2;
  let a = Math.atan2(x, -y) * 180/Math.PI;
  a = Math.max(-135, Math.min(135, a));
  const t = 180 + (a+135)/270*150;
  dialSet(id, STOPS.reduce((b,s)=>Math.abs(s-t)<Math.abs(b-t)?s:b, STOPS[0]));
}
function dialBind(id){
  const svg = document.getElementById(id+'Svg'); if(!svg) return;
  let down=false;
  svg.addEventListener('pointerdown', ev=>{ down=true; try{svg.setPointerCapture(ev.pointerId);}catch(e){} dialFromPointer(id, svg, ev); });
  svg.addEventListener('pointermove', ev=>{ if(down) dialFromPointer(id, svg, ev); });
  svg.addEventListener('pointerup', ()=>{ down=false; });
  svg.addEventListener('pointercancel', ()=>{ down=false; });
}
function dialPaint(id, v){
  const n=document.getElementById(id+'Needle'); if(n) n.style.transform=`rotate(${ang(v)}deg)`;
  const mid=document.getElementById(id+'Mid'); if(mid) mid.textContent=v+'°';
  const svg=document.getElementById(id+'Svg'); if(!svg) return;
  svg.querySelectorAll('.lb').forEach(l=>{ const on=+l.dataset.t===v; l.setAttribute('fill', on?'#2C2825':'#6B6560'); l.setAttribute('font-size', on?'7.6':'6.6'); });
  svg.querySelectorAll('.tk').forEach(k=>{ const on=+k.dataset.t===v; k.setAttribute('stroke', on?'#CFA872':'#2C2825'); k.setAttribute('stroke-width', on?'2.6':((+k.dataset.t-180)%15===0?'1.6':'0.9')); });
}
function dialSync(){
  const t=+document.getElementById('crTemp').value, h=+document.getElementById('crHeat').value;
  dialPaint('crTemp', t); dialPaint('crHeat', h);
  const v1=document.getElementById('dialTempV'), v2=document.getElementById('dialHeatV');
  if(v1) v1.textContent=t+'°C'; if(v2) v2.textContent=h+'°C';
}
function tempModeUI(){
  const dia = crGetSeg('crModel')==='Diamond';
  document.getElementById('tempSliders').style.display = dia ? '' : 'none';
  document.getElementById('tempDials').style.display = dia ? 'none' : '';
}
document.getElementById('dialTemp').innerHTML = dialSVG('crTemp');
document.getElementById('dialHeat').innerHTML = dialSVG('crHeat');
dialBind('crTemp'); dialBind('crHeat');
dialSync(); tempModeUI();


/* ════════ INSTALL + PUSH NOTIFICATIONS ════════
   The permission ask and the preferences work now. The actual subscription is the
   single function pushSubscribe() below — it stays empty until the app is hosted on
   your own domain with /sw.js and /manifest.json, because a service worker cannot
   run from a single HTML file. On hosting day: paste the OneSignal (or FCM) init
   there and nothing else in this file needs to change. */

/* A drawn iPhone showing Safari's share sheet with "Add to Home Screen" picked out. */
function phoneSVG(){
  return `<svg class="iphone" viewBox="0 0 200 330" role="img" aria-label="iPhone share sheet with Add to Home Screen highlighted">
    <rect x="6" y="6" width="188" height="318" rx="26" fill="#1F1B19"/>
    <rect x="12" y="12" width="176" height="306" rx="21" fill="#F5F3EF"/>
    <rect x="76" y="17" width="48" height="8" rx="4" fill="#1F1B19"/>
    <rect x="24" y="36" width="60" height="7" rx="3.5" fill="#D9D4CC"/>
    <rect x="24" y="52" width="152" height="52" rx="10" fill="#E7E2D9"/>
    <circle cx="50" cy="78" r="13" fill="#CFA872" fill-opacity=".5"/>
    <rect x="72" y="70" width="86" height="6" rx="3" fill="#CFC8BE"/>
    <rect x="72" y="82" width="58" height="6" rx="3" fill="#CFC8BE"/>
    
    <g>
      <rect x="12" y="120" width="176" height="198" rx="18" fill="#FFFFFF"/>
      <rect x="82" y="128" width="36" height="4" rx="2" fill="#DCD7CF"/>
      <rect x="24" y="144" width="152" height="30" rx="8" fill="#F5F3EF"/>
      <rect x="34" y="154" width="70" height="5" rx="2.5" fill="#C9C3B9"/>
      <rect x="34" y="163" width="46" height="4" rx="2" fill="#DCD7CF"/>
      <rect x="24" y="182" width="152" height="22" rx="7" fill="#F5F3EF"/>
      <rect x="36" y="190" width="64" height="5" rx="2.5" fill="#C9C3B9"/>
      
      <rect x="20" y="212" width="160" height="30" rx="9" fill="#CFA872" fill-opacity=".16" stroke="#CFA872" stroke-width="1.6"/>
      <rect x="34" y="221" width="10" height="10" rx="2.5" fill="none" stroke="#8a6a3a" stroke-width="1.6"/>
      <path d="M39 223.6v4.8M36.6 226h4.8" stroke="#8a6a3a" stroke-width="1.5" stroke-linecap="round"/>
      <text x="54" y="230.5" font-family="DM Sans, sans-serif" font-size="9" font-weight="700" fill="#8a6a3a">Add to Home Screen</text>
      <circle cx="150" cy="227" r="13" fill="#2C2825" fill-opacity=".1"/>
      <circle cx="150" cy="227" r="7" fill="#2C2825" fill-opacity=".22"/>
      <rect x="24" y="252" width="152" height="22" rx="7" fill="#F5F3EF"/>
      <rect x="36" y="260" width="52" height="5" rx="2.5" fill="#DCD7CF"/>
      <rect x="24" y="282" width="152" height="22" rx="7" fill="#F5F3EF"/>
      <rect x="36" y="290" width="70" height="5" rx="2.5" fill="#DCD7CF"/>
    </g>
  </svg>`;
}

const NT_KEY = 'ensoNotifyMuted';
let ntMuted = false;
try{ ntMuted = localStorage.getItem(NT_KEY) === '1'; }catch(e){}

function isInstalled(){
  return window.navigator.standalone === true ||
         (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches);
}
function isIOS(){ return /iphone|ipad|ipod/i.test(navigator.userAgent); }
function pushState(){
  if(!('Notification' in window)) return isIOS() && !isInstalled() ? 'install' : 'unsupported';
  if(isIOS() && !isInstalled()) return 'install';
  if(Notification.permission === 'granted') return 'on';
  if(Notification.permission === 'denied') return 'denied';
  return 'ask';
}

/* ⬇⬇ HOSTING DAY: this is the only function to fill in. ⬇⬇
   OneSignal:  await OneSignal.init({ appId:'YOUR-APP-ID' }); OneSignal.User.PushSubscription.optIn();
   Firebase:   await getToken(messaging, { vapidKey:'YOUR-VAPID-KEY' }) and POST the token to your server.
   Everyone gets the same broadcast — there are no categories. The only per-device state is
   the pause switch, sent as a tag so paused devices are excluded from a send:
   OneSignal.User.addTags({ muted:String(ntMuted) }); */
async function pushSubscribe(){
  /* no push service wired up yet — the app still remembers the choice below */
  return false;
}
async function pushSyncTags(){
  /* called whenever a toggle changes; same provider call as above */
}

const NTBAR_KEY = 'ensoNtBarHidden';
/* The bar lives under the model tabs on every tab and every screen. It is always there;
   the switch simply reflects where this device stands. */
function renderNtBar(){
  const bar = document.getElementById('ntBar');
  if(!bar) return;
  const st = pushState();
  const live = st === 'on' && !ntMuted;
  const bot = document.getElementById('ntBot');

  /* Once they are on, the sign-up bar is done — the control moves to a slim strip
     above the bottom nav, out of the way but still one tap from pausing. */
  bar.classList.toggle('on', st !== 'on');
  if(bot){
    bot.classList.toggle('on', st === 'on');
    document.body.classList.toggle('ntbot-on', st === 'on');
    document.getElementById('ntBotTxt').textContent = live ? 'Notifications on' : 'Notifications paused';
    document.getElementById('ntBotSw').classList.toggle('on', live);
  }
  if(st === 'on') return;

  const title = document.getElementById('nbTitle'), sub = document.getElementById('nbSub'), sw = document.getElementById('nbSw');
  sw.classList.toggle('on', live);
  if(st === 'install'){
    title.textContent = 'Get software updates first';
    sub.textContent = 'Add ENSŌ to your home screen first — tap to see how.';
  } else if(st === 'denied'){
    title.textContent = 'Notifications are blocked';
    sub.textContent = 'Tap to see how to switch them back on.';
  } else {
    title.textContent = 'Get software updates first';
    sub.textContent = 'Know the moment new firmware lands — plus blends and tricks.';
  }
}
async function ntBarGo(){
  const st = pushState();
  if(st === 'ask'){ await notifyAsk(); renderNtBar(); return; }
  if(st === 'on'){ notifyPause(); renderNtBar(); return; }
  go('notify');   // install, blocked, or unsupported — explain it on the full screen
}
function renderNotify(){
  const st = pushState();
  const phone = document.getElementById('ntPhone');
  const inst = document.getElementById('ntInstall');
  const btn = document.getElementById('ntBtn');
  const note = document.getElementById('ntNote');
  const lead = document.getElementById('ntLead');
  if(!btn) return;
  if(phone && !phone.innerHTML) phone.innerHTML = phoneSVG();
  const reg = document.getElementById('ntReg');
  if(reg) reg.style.display = (profile && profile.devices && profile.devices.length) ? 'none' : '';
  inst.style.display = st === 'install' ? '' : 'none';

  btn.className = 'nt-btn';
  btn.disabled = false;
  if(st === 'install'){
    btn.textContent = 'Add to Home Screen first';
    btn.className = 'nt-btn off'; btn.disabled = true;
    note.textContent = 'Once ENSŌ is on your home screen, open it from that icon and this button turns on.';
  } else if(st === 'ask'){
    btn.textContent = 'Turn on notifications';
    note.textContent = 'Your phone will ask you to allow them. You can pause them here whenever you like.';
  } else if(st === 'on'){
    btn.textContent = 'Notifications are on';
    btn.className = 'nt-btn done'; btn.disabled = true;
    note.textContent = 'Here is what will come through.';
  } else if(st === 'denied'){
    btn.textContent = 'Blocked on this device';
    btn.className = 'nt-btn off'; btn.disabled = true;
    note.textContent = 'Notifications were turned down earlier, so we cannot ask again. Settings → Notifications → ENSŌ to switch them back on.';
  } else {
    btn.textContent = 'Not available here';
    btn.className = 'nt-btn off'; btn.disabled = true;
    note.textContent = 'This browser or preview window cannot receive notifications. Open the app from its own address — on iPhone, from the home screen icon — and this turns on.';
  }

  const pauseRow = document.getElementById('ntPauseRow'), pauseSw = document.getElementById('sw-pause');
  if(pauseRow) pauseRow.style.display = st === 'on' ? '' : 'none';
  if(pauseSw) pauseSw.classList.toggle('on', ntMuted);
  if(st === 'on' && ntMuted){
    btn.textContent = 'Notifications are paused';
    btn.className = 'nt-btn off';
    note.textContent = 'Nothing will come through until you switch the pause back off below.';
  }
}
async function notifyAsk(){
  const st = pushState();
  if(st !== 'ask') return;
  try{
    const res = await Notification.requestPermission();
    if(res === 'granted'){
      await pushSubscribe();
      try{ new Notification('ENSŌ', {body:"You're in. Software updates, first looks and new blends — nothing else."}); }catch(e){}
    }
  }catch(e){}
  renderNotify();
  renderNtBar();
}
function notifyPause(){
  if(pushState() !== 'on') return;
  ntMuted = !ntMuted;
  try{ localStorage.setItem(NT_KEY, ntMuted ? '1' : '0'); }catch(e){}
  pushSyncTags();
  renderNotify();
}


/* ════════ WARRANTY REGISTRATION + PROFILE ════════
   Registration is what activates the warranty and what ties a device to its software
   updates. Everything is kept on the phone for now; sendRegistration() below is the one
   call to fill in once there is a backend (a Shopify customer, a sheet, or your own API). */
const PROF_KEY = 'ensoProfile';
const REG_KEY  = 'ensoRegistry';   /* serial → registration, kept even after signing out */
let profile = null;
try{ profile = JSON.parse(localStorage.getItem(PROF_KEY) || 'null'); }catch(e){}
function profileSave(){
  try{ localStorage.setItem(PROF_KEY, JSON.stringify(profile)); }catch(e){}
  registrySave();
  renderProfBtn();
}
/* Every registration is also filed by serial number. Entering the same serial and the
   same email brings the whole profile back — no password, no confirmation email.
   On one phone this works today; across phones it needs the backend lookup below. */
function registryAll(){
  try{ return JSON.parse(localStorage.getItem(REG_KEY) || '{}'); }catch(e){ return {}; }
}
function registrySave(){
  if(!profile || !profile.devices) return;
  const all = registryAll();
  profile.devices.forEach(d=>{
    all[regKey(d.serial)] = {name:profile.name, email:profile.email, device:d};
  });
  try{ localStorage.setItem(REG_KEY, JSON.stringify(all)); }catch(e){}
}
function regKey(serial){ return String(serial||'').toUpperCase().replace(/\s+/g,''); }

/* ⬇⬇ HOSTING DAY: the same lookup against your server, so a profile follows the person
   to a new phone. Return the stored registration for this serial, or null.
   e.g. const r = await fetch(`/api/registration?serial=${encodeURIComponent(serial)}`).then(r=>r.json()); */
async function lookupRegistration(serial){
  return registryAll()[regKey(serial)] || null;
}
function profInitials(nm){ return (nm||'').trim().split(/\s+/).slice(0,2).map(w=>w[0]||'').join('').toUpperCase() || '⌂'; }

/* ⬇⬇ HOSTING DAY: send the registration somewhere that outlives the phone. ⬇⬇
   e.g. await fetch('/api/register', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(dev)});
   and tag the push subscription with the model so firmware notices only reach that device:
   OneSignal.User.addTags({ device: dev.model, serial: dev.serial }); */
async function sendRegistration(dev){ return true; }

function renderProfBtn(){
  const av = document.getElementById('pbAv'), txt = document.getElementById('pbTxt');
  if(!av) return;
  if(profile && profile.devices && profile.devices.length){
    av.textContent = profInitials(profile.name);
    txt.textContent = profile.name.trim().split(/\s+/)[0] || 'Profile';
  } else {
    av.textContent = '⌂';
    txt.textContent = 'Register warranty';
  }
}

/* ── onboarding: 1 register · 2 home screen · 3 updates ── */
const OB_KEY = 'ensoOnboard';
function obStage(){ try{ return localStorage.getItem(OB_KEY) || ''; }catch(e){ return ''; } }
function obSet(v){ try{ localStorage.setItem(OB_KEY, v); }catch(e){} }
function obNext(step){
  if(step === 'notify'){
    obSet('notify');
    go('ob-notify');
    const note = document.getElementById('obNotifyNote'), btn = document.getElementById('obNotifyBtn');
    const st = pushState();
    if(st === 'on'){ btn.textContent = 'Updates are on'; btn.disabled = true; note.textContent = 'Already on for this device.'; }
    else if(st === 'install'){ note.textContent = "Open ENSŌ from the home screen icon and this will work — we'll ask you again there."; }
    else if(st === 'denied'){ note.textContent = 'Notifications are blocked for this app. Settings → Notifications → ENSŌ switches them back on.'; }
    else note.textContent = '';
    return;
  }
  go(step);
}
async function obAskNotify(){
  if(pushState() === 'ask') await notifyAsk();
  else go('notify');
  renderNtBar();
  if(pushState() === 'on') obFinish();
}
function obFinish(){
  obSet('done');
  renderProfile(true);
  go('profile');
  renderNtBar();
  lsSet('enso_tour_v1', false);
  setTimeout(()=>startTour(true), 1200);
}
function obResume(){
  if(!isRegistered()) return false;
  const st = obStage();
  if(st === 'done' || st === '') return false;
  if(st === 'install'){ document.getElementById('obPhone').innerHTML = phoneSVG(); go('ob-install'); return true; }
  if(st === 'notify'){ obNext('notify'); return true; }
  return false;
}

function isRegistered(){ return !!(profile && profile.devices && profile.devices.length); }
function applyGate(){
  const locked = !isRegistered();
  document.body.classList.toggle('gated', false);
  const note = document.getElementById('gateNote');
  if(note) note.style.display = locked ? '' : 'none';
}
function goProfile(){ go(isRegistered() ? 'profile' : 'register'); }
function regOpen(){ obSet('done'); go('register'); }

function regShot(){
  const pick = crGetSeg('regModel');
  const key = pick === 'Diamond' ? 'diamond' : (pick === 'ENSŌ 2.0' ? 'enso2' : 'enso');
  const st = key === 'enso' ? REG_AWARD : (STAGE_BY_MODEL[key] || STAGE_BY_MODEL.enso);
  const img = document.getElementById('regShot');
  if(img){ img.src = st.src; document.getElementById('regShotCap').textContent = st.cap; }
}
let regOpenedAt = Date.now();
/* ⬇⬇ HOSTING DAY: add Cloudflare Turnstile here if junk registrations ever start.
   It is free, needs no cookie banner, and is the GDPR-friendly choice over reCAPTCHA:
   render the widget on this screen and send its token with sendRegistration(). */
function regBotSuspect(){
  const trap = document.getElementById('regNick');
  if(trap && trap.value) return 'trap';                       // only a script fills a hidden field
  if(Date.now() - regOpenedAt < 4000) return 'fast';          // nobody types a serial in four seconds
  return '';
}
function regValidate(){
  const serial = document.getElementById('regSerial').value.trim().toUpperCase();
  document.getElementById('regSerial').value = serial;
  const name = document.getElementById('regName').value.trim();
  const mail = document.getElementById('regEmail').value.trim();
  const agreed = document.getElementById('regAgree').checked;
  const ok = serial.length >= 3 && name.length > 1 && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(mail) && agreed;
  document.getElementById('regBtn').disabled = !ok;
  return ok;
}
async function regSubmit(){
  const err = document.getElementById('regErr');
  const serial = document.getElementById('regSerial').value.trim();
  const name = document.getElementById('regName').value.trim();
  const mail = document.getElementById('regEmail').value.trim();
  const date = document.getElementById('regDate').value;
  if(!regValidate()) return err.textContent = document.getElementById('regAgree').checked
    ? 'We need the serial number, your name and a valid email.'
    : 'Please confirm the line above before registering.';
  const bot = regBotSuspect();
  if(bot === 'trap') return;                                   // silence is the right answer to a bot
  if(bot === 'fast') return err.textContent = 'Give that one more second and try again.';
  if(profile && profile.devices && profile.devices.some(d=>regKey(d.serial) === regKey(serial)))
    return err.textContent = 'That serial number is already on this profile.';
  err.textContent = '';

  /* known serial? then this is someone coming back, not a new registration */
  const known = await lookupRegistration(serial);
  if(known){
    if(known.email.toLowerCase() !== mail.toLowerCase()){
      return err.textContent = 'This serial is already registered to a different email address. Use that address, or email ' + SUPPORT + ' if the device changed hands.';
    }
    profile = profile || {name:known.name, email:known.email, devices:[]};
    profile.name = known.name; profile.email = known.email;
    profile.devices = (profile.devices || []).concat([known.device]);
    profileSave();
    document.getElementById('regSerial').value = '';
    applyGate(); renderNtBar(); obSet('done');
    renderProfile(false);
    go('profile');
    err.textContent = '';
    return;
  }

  const dev = {
    model: e2Label(crGetSeg('regModel')),
    serial, bought: date || '',
    where: crGetSeg('regWhere'),
    order: document.getElementById('regOrder').value.trim(),
    fw: '',
    at: Date.now()
  };
  if(profile && profile.email && profile.email.toLowerCase() !== mail.toLowerCase())
    return err.textContent = 'Your profile uses ' + profile.email + '. Devices are added under that address.';
  await sendRegistration(Object.assign({name, email:mail, consentAt:new Date().toISOString(), consentText:'18+, owner, Terms + Privacy Notice'}, dev));
  profile = profile || {name:'', email:'', devices:[]};
  profile.name = name; profile.email = mail;
  profile.devices = (profile.devices || []).concat([dev]);
  profileSave();
  ['regSerial','regOrder'].forEach(id=>document.getElementById(id).value='');
  applyGate();
  renderNtBar();
  obSet('done');
  renderProfile(true);
  go('profile');
}

/* ════════ SOFTWARE RELEASES ════════
   ⚠️ EDIT THIS when you ship firmware. One block per model: version, release date
   (YYYY-MM-DD) and what changed. The app compares this date with the date the owner
   says they last updated — a phone cannot read the firmware off the device itself. */
const FIRMWARE = {
  /* ⚠️ ver / notes / how are still empty — send them and they appear in the panel. */
  "ENSŌ":       {ver:"", date:"2026-10-01", notes:[], how:[]},
  "ENSŌ 2.0":   {ver:"", date:"2026-10-01", notes:[], how:[]},
  "Diamond":    {ver:"", date:"2026-10-01", notes:[], how:[]}
};
const FW_SUGGEST = "2026-10-02";   /* date the picker opens on when nobody has said yet */
function fwFor(model){ return FIRMWARE[model] || null; }
function fwStatus(dev){
  const f = fwFor(dev.model);
  if(!f || !f.date) return {state:'none', f:f};
  if(!dev.fw) return {state:'unknown', f:f};
  return {state: (new Date(dev.fw) >= new Date(f.date)) ? 'ok' : 'due', f:f};
}
function fwBlock(dev, i){
  const st = fwStatus(dev), f = st.f;
  if(!f || !f.date){
    return `<div class="fw-row" style="cursor:default"><span class="fw-ico" style="background:#E5E1DA;color:#9B9590">i</span>
      <span class="fw-txt"><b>Software</b><span>No release published yet — we will tell you here when there is one.</span></span></div>`;
  }
  const label = st.state === 'ok' ? 'Software is up to date'
              : st.state === 'due' ? 'Software update available'
              : 'Have you updated your software?';
  const v = f.ver ? `Version ${f.ver}` : 'Latest release';
  const sub = st.state === 'ok' ? `${v} · you updated ${fmtDate(new Date(dev.fw))}`
            : st.state === 'due' ? `${v} from ${fmtDate(new Date(f.date))} · yours is from ${fmtDate(new Date(dev.fw))}`
            : `${v} from ${fmtDate(new Date(f.date))} · tell us when you last updated`;
  const cls = st.state === 'ok' ? 'ok' : (st.state === 'due' ? 'due' : '');
  const icon = st.state === 'ok' ? '✓' : '!';
  return `<button class="fw-row ${cls}" id="fwRow${i}" onclick="fwToggle(${i})">
      <span class="fw-ico">${icon}</span>
      <span class="fw-txt"><b>${label}</b><span>${sub}</span></span>
      <span class="fw-arrow">›</span>
    </button>
    <div class="fw-panel" id="fwPanel${i}">
      <h4>${f.ver ? 'VERSION ' + f.ver + ' · ' : ''}RELEASED ${fmtDate(new Date(f.date)).toUpperCase()}</h4>
      ${f.notes.length ? '' : '<p style="font-size:12.5px;color:var(--ink-2);line-height:1.55;margin-bottom:10px">A new software release is out for this device. Update it, then set the date below so your profile stays accurate.</p>'}
      ${f.notes.length ? `<ul>${f.notes.map(n=>`<li>${n}</li>`).join('')}</ul>` : ''}
      ${f.how.length ? `<h4>HOW TO UPDATE</h4><ul>${f.how.map(n=>`<li>${n}</li>`).join('')}</ul>` : ''}
      <h4>WHEN DID YOU LAST UPDATE?</h4>
      <div class="fw-when">
        <input type="date" id="fwDate${i}" value="${dev.fw || FW_SUGGEST}" max="${new Date().toISOString().slice(0,10)}">
        <button class="fw-save" onclick="fwSave(${i})">Save</button>
      </div>
      <div class="fw-note">We cannot read the software version off your device, so this is the date you tell us. Set it and the check mark above keeps itself honest.</div>
    </div>`;
}
function fwToggle(i){
  const row = document.getElementById('fwRow'+i), panel = document.getElementById('fwPanel'+i);
  const open = panel.classList.toggle('open');
  if(row) row.classList.toggle('open', open);
}
function fwSave(i){
  const val = document.getElementById('fwDate'+i).value;
  if(!val) return;
  profile.devices[i].fw = val;
  profileSave();
  renderProfile(false);
  setTimeout(()=>fwToggle(i), 50);
}

function warrantyEnd(dev, years){
  const base = dev.bought ? new Date(dev.bought) : new Date(dev.at);
  if(isNaN(base)) return null;
  const d = new Date(base); d.setFullYear(d.getFullYear() + years); return d;
}
function fmtDate(d){ return d ? d.toLocaleDateString(undefined, {day:'numeric', month:'short', year:'numeric'}) : '—'; }
function renderProfile(justRegistered){
  if(!profile) return;
  document.getElementById('pfAv').textContent = profInitials(profile.name);
  document.getElementById('pfName').textContent = profile.name || 'Your profile';
  document.getElementById('pfMail').textContent = profile.email || '';
  document.getElementById('pfLock').textContent = profile.email ? 'Locked to your serial numbers — this is how you get back in' : '';
  const sup = document.getElementById('pfSupport');
  sup.onclick = ()=>{ location.href = `mailto:${SUPPORT}?subject=${encodeURIComponent('ENSŌ support — ' + (profile.devices[0] ? profile.devices[0].serial : ''))}`; };
  const wrap = document.getElementById('pfDevices');
  const ok = justRegistered ? `<div class="wr-ok"><div class="wo-check">✓</div><h3>Warranty active</h3>
      <p>You're registered and signed in on this phone. Turn notifications on and you will hear the moment new software is out for this exact device.</p>
      <button class="nt-btn" style="margin-top:12px" onclick="go('notify')">Turn on update alerts</button></div>` : '';
  wrap.innerHTML = ok + profile.devices.map((d, i)=>{
    const dev2 = warrantyEnd(d, 2), bat = warrantyEnd(d, 1);
    const live = dev2 && dev2 > new Date();
    return `<div class="dev-card">
      <div class="dev-top"><b>${e2Label(d.model)}</b><span class="dev-pill ${live?'':'out'}">${live?'WARRANTY ACTIVE':'WARRANTY ENDED'}</span></div>
      <div class="dev-row"><span>Model</span><b>${e2Label(d.model)}</b></div>
      <div class="dev-row"><span>Serial</span><b>${d.serial}</b></div>
      <div class="dev-row"><span>Bought</span><b>${d.bought ? fmtDate(new Date(d.bought)) : '—'}${d.where ? ' · ' + d.where : ''}</b></div>
      ${d.order ? `<div class="dev-row"><span>Order</span><b>${d.order}</b></div>` : ''}
      <div class="dev-row"><span>Device cover until</span><b>${fmtDate(dev2)}</b></div>
      <div class="dev-row"><span>Battery cover until</span><b>${fmtDate(bat)}</b></div>
      ${fwBlock(d, i)}
    </div>`;
  }).join('');
}
function profileSignOut(){
  if(!confirm('Sign out of this phone? Your warranty stays registered. Entering the same serial number and email brings your profile back.')) return;
  profile = null;
  try{ localStorage.removeItem(PROF_KEY); }catch(e){}
  try{ localStorage.removeItem(OB_KEY); }catch(e){}
  renderProfBtn();
  renderNtBar();
  applyGate();
}

/* ════════ FIRST-VISIT TOUR ════════ */
const TOUR = [
  {sel:'.search-wrap',                 t:'Ask anything',      x:'Type a question the way you\'d ask a friend — "why is my vapor weak", "how do I clean it". Answers come with pictures.'},
  {sel:'.nav button[data-s="howto"]',  t:'How to use',        x:'Step-by-step guides for setup, packing, temperature, modes and cleaning — every step shown on the screen up top.'},
  {sel:'.nav button[data-s="fix"]',    t:'Something off?',    x:'Troubleshoot walks you through fixes for weak clouds, charging, harsh taste and more — and connects you to support if needed.'},
  {sel:'.nav button[data-s="recipes"]',t:'Feeling creative?', x:'Build your own flavor blend, or get inspired by the community\'s recipes. Share yours as a card.'},
  {sel:'#wnPill',                      t:'What\'s new',       x:'Product news and accessories that boost performance — tap this pill any time to see what\'s new for your device.'},
  {sel:'#profBtn',                     t:'Your profile',       x:'Your warranty, serial numbers and cover dates live here. Register another device from the same place.'},
  {sel:'.model-tabs',                  t:'Keep it one tap away', x:'Add ENSŌ to your home screen — it opens like an app, and it is the only way an iPhone can tell you when new software is out for your device.', html:true}
];
let tourI = 0;
function startTour(force){
  if(typeof isRegistered === 'function' && !isRegistered()) return;   // register first
  if(typeof obStage === 'function' && obStage() && obStage() !== 'done') return;  // finish onboarding first
  if(!force && ls('enso_tour_v1', false)) return;
  setModel(SHOW_E2 ? 'enso2' : 'enso'); go('search');
  tourI = 0; document.getElementById('tour').classList.add('on'); tourShow();
}
function tourShow(){
  const s = TOUR[tourI]; const el = document.querySelector(s.sel); if(!el) return tourNext();
  const isNav = s.sel.startsWith('.nav');
  if(!isNav && s.sel!=='#wnPill') el.scrollIntoView({block:'center', behavior:'instant'});
  setTimeout(()=>{
    const r = el.getBoundingClientRect(), pad = isNav ? 6 : 8;
    const spot = document.getElementById('tourSpot');
    spot.style.left = (r.left-pad)+'px'; spot.style.top = (r.top-pad)+'px';
    spot.style.width = (r.width+pad*2)+'px'; spot.style.height = (r.height+pad*2)+'px';
    spot.style.borderRadius = isNav ? '16px' : '20px';
    const b = document.getElementById('tourBubble');
    document.getElementById('tourStep').textContent = `STEP ${tourI+1} OF ${TOUR.length}`;
    document.getElementById('tourTitle').textContent = s.t;
    if(s.html){
      document.getElementById('tourText').innerHTML =
        `${s.x}${phoneSVG()}<ol class="inst-steps"><li>Tap <b>Share</b> in Safari.</li><li>Tap <b>Add to Home Screen</b>.</li><li>Open ENSŌ from the new icon.</li></ol>` +
        `<button class="nt-link" style="width:100%;margin-top:6px" onclick="endTour();go('notify')">Set up notifications</button>`;
    } else {
      document.getElementById('tourText').textContent = s.x;
    }
    document.getElementById('tourDots').innerHTML = TOUR.map((_,i)=>`<i class="${i===tourI?'on':''}"></i>`).join('');
    document.getElementById('tourNext').textContent = tourI===TOUR.length-1 ? 'Start using ENSŌ' : 'Next';
    const app = document.querySelector('.app').getBoundingClientRect();
    const bw = Math.min(s.html ? 320 : 300, window.innerWidth-32);
    let left = Math.max(app.left+16, Math.min(r.left, app.right-16-bw));
    b.style.left = left+'px'; b.style.width = bw+'px';
    b.classList.remove('above','below');
    const bh = s.html ? Math.min(430, window.innerHeight*0.62) : 170;
    if(r.bottom + 12 + bh < window.innerHeight - 20){ b.style.top = (r.bottom+16)+'px'; b.classList.add('below'); }
    else { b.style.top = (r.top-16-bh)+'px'; b.classList.add('above'); }
    b.style.setProperty('--ax', Math.max(20, Math.min(r.left + r.width/2 - left - 8, bw-36))+'px');
  }, 60);
}
function tourNext(){ tourI++; if(tourI>=TOUR.length) return endTour(); tourShow(); }
function endTour(){ document.getElementById('tour').classList.remove('on'); lsSet('enso_tour_v1', true); document.getElementById('wrap').scrollTop = 0; }
applyE2Visibility();
setModel(model);
renderNtBar();
renderProfBtn();
applyGate();
obResume();

/* ── Preview any screen without registering: add ?screen=<id> to the URL. ──
   For review and for whoever hosts this. Examples:
     ?screen=register   ?screen=ob-install   ?screen=ob-notify
     ?screen=profile    ?screen=notify       ?screen=diamond
   ?reset=1 clears registration, onboarding and notification state on this device. */
(function previewFromUrl(){
  const q = new URLSearchParams(location.search);
  if(q.get('reset')){
    ['ensoProfile','ensoOnboard','ensoNotifyMuted','enso_tour_v1'].forEach(k=>{ try{ localStorage.removeItem(k); }catch(e){} });
    location.replace(location.pathname);
    return;
  }
  const want = q.get('screen');
  if(!want) return;
  const el = document.getElementById('scr-' + want);
  if(!el) return;
  if(typeof endTour === 'function') endTour();
  document.body.classList.remove('gated');
  document.querySelectorAll('.scr').forEach(x=>x.classList.remove('active'));
  el.classList.add('active');
  document.body.classList.toggle('onboarding', want.indexOf('ob-') === 0);
  if(want === 'ob-install') document.getElementById('obPhone').innerHTML = phoneSVG();
  if(want === 'register'){ regValidate(); regShot(); document.body.classList.add('gated'); }
  if(want === 'profile' && isRegistered()) renderProfile(false);
  if(want === 'notify') renderNotify();
  document.getElementById('wrap').scrollTop = 0;
})();

/* ════════ site build: deep links from ENSŌ Experience ════════
   app.html#register  #warranty  #updates  #fix  #recipes  #howto  #search
   prefix diamond- or enso- picks the device first, e.g. #diamond-fix. Until a warranty is registered every link lands on registration. */
function ensoDeep(){
  let h = (location.hash || '').slice(1).toLowerCase(); if(!h) return false;
  const MAP = {register:'register', warranty:'register', updates:'sw', software:'sw', notify:'sw', fix:'fix', troubleshooting:'fix', troubleshoot:'fix', recipes:'recipes', blends:'recipes', howto:'howto', guides:'howto', search:'search', profile:'register'};
  let dev = null; const m = h.match(/^(diamond|enso)-(.+)$/); if(m){ dev = m[1]; h = m[2]; } else if(h === 'diamond' || h === 'enso'){ dev = h; h = 'home'; }
  const scr = h === 'home' ? 'home' : MAP[h]; if(!scr) return false;
  if(typeof endTour === 'function') endTour();
  if(dev) saDevice(dev);   /* the QR on the box says which device */
  else if(!saHasDevice() && scr === 'home'){ go('start'); return true; }
  else if(!saHasDevice() && scr !== 'register') saTemp(scr === 'sw' ? 'diamond' : 'enso');   /* straight to the section, switch in one tap */
  if(scr === 'register'){ isRegistered() ? goProfile() : go('register'); } else go(scr);
  return true;
}
window.addEventListener('hashchange', ensoDeep);

/* theme: phone setting → light → dark */
const TH_ICON = {
  '':     '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8"/><path d="M12 4a8 8 0 0 1 0 16z" fill="currentColor" stroke="none"/></svg>',
  light:  '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="4"/><path d="M12 2.5v2M12 19.5v2M2.5 12h2M19.5 12h2M5.3 5.3l1.4 1.4M17.3 17.3l1.4 1.4M5.3 18.7l1.4-1.4M17.3 6.7l1.4-1.4"/></svg>',
  dark:   '<svg viewBox="0 0 24 24"><path d="M20 14.5A8 8 0 1 1 9.5 4a6.5 6.5 0 0 0 10.5 10.5z"/></svg>'};
const TH_NAME = {'':'System settings', light:'Light', dark:'Dark'};
function themeNow(){ return document.documentElement.dataset.theme || ''; }
function themeUI(){
  const v = themeNow(), b = document.getElementById('themeBtn');
  const isDark = v === 'dark' || (!v && matchMedia('(prefers-color-scheme: dark)').matches);
  if(b){ b.innerHTML = TH_ICON[v]; b.setAttribute('aria-label', 'Theme: ' + TH_NAME[v].toLowerCase() + '. Tap to change'); b.title = 'Theme: ' + TH_NAME[v]; }
  const mc = document.querySelector('meta[name="theme-color"]'); if(mc) mc.content = isDark ? '#141210' : '#FFFFFF';
}
let _thTip = null;
function cycleTheme(){
  const order = ['', 'light', 'dark'], v = order[(order.indexOf(themeNow()) + 1) % 3], r = document.documentElement;
  if(v) r.dataset.theme = v; else delete r.dataset.theme;
  try{ v ? localStorage.setItem('ensoTheme', v) : localStorage.removeItem('ensoTheme'); }catch(e){}
  themeUI();
  let t = document.getElementById('themeTip'); if(!t){ t = document.createElement('div'); t.id = 'themeTip'; t.className = 'theme-tip'; t.setAttribute('role','status'); document.body.appendChild(t); }
  t.textContent = 'Theme: ' + TH_NAME[v]; t.classList.add('on'); clearTimeout(_thTip); _thTip = setTimeout(()=>t.classList.remove('on'), 1400);
}
try{ matchMedia('(prefers-color-scheme: dark)').addEventListener('change', themeUI); }catch(e){}
themeUI();

/* support address in the static markup follows the region too */
(function(){
  if(SUPPORT === 'support@ensoshisha.com') return;
  const fix = root => {
    root.querySelectorAll && root.querySelectorAll('a[href^="mailto:support@ensoshisha.com"]').forEach(a => {
      a.href = a.getAttribute('href').replace('support@ensoshisha.com', SUPPORT);
      if(a.textContent.trim() === 'support@ensoshisha.com') a.textContent = SUPPORT;
    });
  };
  fix(document);
  new MutationObserver(ms => ms.forEach(m => m.addedNodes.forEach(n => n.nodeType === 1 && fix(n.parentNode || n)))).observe(document.body, {childList:true, subtree:true});
})();
